(()=>{const panel=document.getElementById('product-panel'),tabs=Array.from(document.querySelectorAll('[data-module]'));const head=(title,subtitle,chip)=>`<div class="panel-intro"><div><h3>${title}</h3><p>${subtitle}</p></div><span class="panel-chip">${chip}</span></div>`;const panels={orders:head('Tus pedidos, al día.','De la primera conversación a la entrega.','3 pedidos')+`<div class="sample-summary"><div><small>Pedidos por entregar</small><strong>2 <span>en seguimiento</span></strong></div><div><small>Clientes organizados</small><strong>3 <span>en tu negocio</span></strong></div></div><div class="sample-labels"><span>CLIENTE / PRODUCTO</span><span>ESTADO</span><span>IMPORTE</span></div><div class="sample-row"><div class="sample-client"><span class="sample-avatar">MC</span><div><strong>María Castillo</strong><small>Torta de chocolate</small></div></div><span class="sample-status">En proceso</span><b>S/ 85</b></div><div class="sample-row"><div class="sample-client"><span class="sample-avatar">JL</span><div><strong>José López</strong><small>Box de cupcakes</small></div></div><span class="sample-status green">Entregado</span><b>S/ 45</b></div><div class="sample-row"><div class="sample-client"><span class="sample-avatar">AP</span><div><strong>Ana Paredes</strong><small>Cheesecake familiar</small></div></div><span class="sample-status amber">Pendiente</span><b>S/ 70</b></div>`,costs:head('Un precio que tiene sentido.','Conoce cuánto cuesta y cuánto deja cada producto.','Cálculo de ejemplo')+`<div class="cost-preview"><div class="cost-inputs"><div><small>Insumos</small><strong>S/ 20.00</strong></div><div><small>Otros costos</small><strong>S/ 5.00</strong></div><div><small>Recargo</small><strong>40%</strong></div><div><small>Unidades</small><strong>1</strong></div></div><div class="cost-answer"><small>PRECIO SUGERIDO</small><strong>S/ 35</strong><p>Costo: S/ 25<br>Ganancia: S/ 10 por unidad.</p></div></div><p class="preview-footnote">Diferencia entre recargo y margen, considera todos tus costos y guarda tus productos o servicios en el catálogo.</p>`,finances:head('Tus números, sin enredos.','Ingresos menos gastos. Más claridad para decidir.','Balance de ejemplo')+`<div class="finance-preview"><div class="sample-summary"><div><small>Ingresos</small><strong>S/ 240</strong></div><div><small>Gastos</small><strong>S/ 95</strong></div><div><small>Balance</small><strong>S/ 145</strong></div></div><div class="preview-chart"><div><i style="height:40%"></i><i style="height:25%"></i></div><div><i style="height:63%"></i><i style="height:37%"></i></div><div><i style="height:53%"></i><i style="height:23%"></i></div><div><i style="height:83%"></i><i style="height:42%"></i></div><div><i style="height:72%"></i><i style="height:31%"></i></div><div><i style="height:95%"></i><i style="height:38%"></i></div></div><div class="chart-days"><span>LUN</span><span>MAR</span><span>MIÉ</span><span>JUE</span><span>VIE</span><span>SÁB</span></div></div><p class="preview-footnote">Los pedidos entregados generan su ingreso automáticamente. Registra todos tus gastos para completar tu balance.</p>`,reminders:head('Una agenda para tu negocio.','Que tus pendientes no dependan de tu memoria.','HOY')+`<div class="reminder-preview"><div><span class="time-block">10:00</span><div><strong>Entregar la torta de María</strong><small>Entrega · Pedido de repostería</small></div><i class="preview-check"></i></div><div><span class="time-block">14:00</span><div><strong>Confirmar el pago de Ana</strong><small>Pago · Revisar seña del pedido</small></div><i class="preview-check"></i></div><div><span class="time-block">17:00</span><div><strong>Preparar pedidos de mañana</strong><small>Cita · Organización del negocio</small></div><i class="preview-check"></i></div></div><p class="preview-footnote">Organiza pagos, entregas y citas; identifica vencimientos y marca lo que ya resolviste.</p>`,copilot:head('Una ayuda para tu próximo paso.','Ideas, resúmenes y respuestas a la mano.','Copilot de prueba')+`<div class="copilot-preview"><p class="preview-question">¿Qué tengo pendiente en mi negocio?</p><div class="preview-response"><span>✦ TU COPILOT</span><p>Tienes <strong>2 pedidos por entregar</strong> y una agenda que revisar.<br><br>→ Confirma la entrega de la torta de María.<br>→ Revisa la seña del pedido de Ana.<br>→ Registra tus gastos de hoy para completar el balance.</p></div><p class="preview-footnote">Asistente de prueba basado en reglas y datos locales. No utiliza un modelo de IA externo ni envía mensajes automáticamente.</p></div>`};function select(tab,focus=false){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});panel.innerHTML=panels[tab.dataset.module];panel.setAttribute('aria-labelledby',tab.id);if(focus)tab.focus();}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{let next;if(['ArrowRight','ArrowDown'].includes(e.key))next=(index+1)%tabs.length;else if(['ArrowLeft','ArrowUp'].includes(e.key))next=(index-1+tabs.length)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();select(tabs[next],true);tabs[next].scrollIntoView({block:'nearest',inline:'nearest'});});});const orientation=matchMedia('(max-width:950px)');const updateOrientation=()=>document.querySelector('.product-tabs').setAttribute('aria-orientation',orientation.matches?'horizontal':'vertical');orientation.addEventListener('change',updateOrientation);updateOrientation();select(tabs[0]);})();
